UPDATE orders
   SET status = 'CANCELED',
       canceled_at = CURRENT_TIMESTAMP(6),
       cancel_reason = #{reason},
       canceled_by = #{canceledBy}
 WHERE id = #{orderId}
   AND status = #{currentStatus}

